  @doc """
  Applies corrected stroke data to all missing kanji in the database.
  """
  def apply do
    Logger.info("Loading embedded stroke data...")
    stroke_data_by_char = load_stroke_data()
    Logger.info("Embedded data loaded: #{map_size(stroke_data_by_char)} kanji")

    affected_chars = Map.keys(stroke_data_by_char)
    kanji_to_fix = Repo.all(from k in Kanji, where: k.character in ^affected_chars)

    results =
      Enum.reduce(kanji_to_fix, %{updated: 0, skipped: 0, errors: []}, fn kanji, acc ->
        case update_kanji(kanji, stroke_data_by_char) do
          {:ok, :updated} ->
            Map.update!(acc, :updated, &(&1 + 1))

          {:error, reason} ->
            acc
            |> Map.update!(:errors, &[reason | &1])
            |> Map.update!(:skipped, &(&1 + 1))
        end
      end)

    Logger.info("Missing kanji stroke fix complete!")
    Logger.info("  Updated: #{results.updated}")
    Logger.info("  Skipped: #{results.skipped}")

    if results.errors != [] do
      Logger.warning("  Errors: #{length(results.errors)}")

      Enum.take(results.errors, 10)
      |> Enum.each(fn err -> Logger.warning("    #{err}") end)
    end

    {:ok, results}
  end

  defp load_stroke_data do
    @compressed_data
    |> Enum.join()
    |> Base.decode64!()
    |> :zlib.gunzip()
    |> Jason.decode!()
  end

  defp update_kanji(kanji, stroke_data_by_char) do
    corrected_stroke_data = Map.get(stroke_data_by_char, kanji.character)

    if corrected_stroke_data do
      # Preserve existing decomposition/etymology if not in corrected data
      merged =
        case kanji.stroke_data do
          nil ->
            corrected_stroke_data

          existing ->
            corrected_stroke_data
            |> maybe_preserve(existing, "decomposition")
            |> maybe_preserve(existing, "etymology")
        end

      case Repo.update(Ecto.Changeset.change(kanji, stroke_data: merged)) do
        {:ok, _} ->
          Logger.debug("Updated strokes for: #{kanji.character}")
          {:ok, :updated}

        {:error, changeset} ->
          Logger.error("Failed to update #{kanji.character}: #{inspect(changeset.errors)}")
          {:error, "#{kanji.character}: #{inspect(changeset.errors)}"}
      end
    else
      {:ok, :skipped}
    end
  end

  defp maybe_preserve(corrected, existing, key) do
    if existing[key] && !corrected[key] do
      Map.put(corrected, key, existing[key])
    else
      corrected
    end
  end
end
